import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void max_reduce_dim1_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner)
{
  // Flatten (outer, inner) into a single index space and use a grid-stride
  // loop so that a grid sized to exactly fill the GPU (no partial tail wave)
  // can process an arbitrary amount of work.
  int64_t total = (int64_t)Outer * (int64_t)Inner;
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (; idx < total; idx += stride) {
    int outer = (int)(idx / Inner);
    int inner = (int)(idx % Inner);
    const T* __restrict__ base = X + (int64_t)outer * Reduce * Inner + inner;
    T maxval = base[0];
    #pragma unroll 4
    for (int r = 1; r < Reduce; ++r) {
      T v = base[(int64_t)r * Inner];
      maxval = v > maxval ? v : maxval;
    }
    Y[idx] = maxval;
  }
}
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  int64_t ndim = x.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  auto x_c = x.contiguous();
  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  int64_t reduce = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);
  // Build output shape: input shape with `dim` removed.
  std::vector<int64_t> out_shape;
  out_shape.reserve(ndim - 1);
  for (int64_t i = 0; i < ndim; ++i) {
    if (i != dim) out_shape.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_shape, x_c.options());
  constexpr int Threads = 256;
  int64_t total_work = outer * inner;
  // Size the grid to avoid a large partial tail wave: launch enough blocks
  // to keep the GPU busy (a fixed multiple of the SM count), and let each
  // thread process multiple elements via the grid-stride loop above.
  int device = 0;
  cudaGetDevice(&device);
  int sm_count = 1;
  cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
  int blocks_per_sm = 1;
  cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, max_reduce_dim1_kernel<float>, Threads, 0);
  if (blocks_per_sm < 1) blocks_per_sm = 1;
  int64_t needed_blocks = (total_work + Threads - 1) / Threads;
  int64_t blocks_per_wave = (int64_t)sm_count * (int64_t)blocks_per_sm;
  if (blocks_per_wave < 1) blocks_per_wave = 1;
  int64_t waves = (needed_blocks + blocks_per_wave - 1) / blocks_per_wave;
  if (waves < 1) waves = 1;
  int64_t grid_blocks = waves * blocks_per_wave;
  if (grid_blocks < 1) grid_blocks = 1;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream();
  max_reduce_dim1_kernel<float><<<(unsigned int)grid_blocks, Threads, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)reduce, (int)inner
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_dim_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Max reduction over a specific dimension,
    implemented with a custom CUDA kernel using CuTe tensor abstractions.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim_forward(x, self.dim)

